use oasis_uep::{recovery::{Recovery,Input,Decision},infrastructure::{Infrastructure,Conditions},priority::Engine,population::Period,bridge::Shares};
fn input(inflow:u64,demand:u64,funding:u64,maintenance:u64)->Input{Input{period:Period{enter:vec![],depart:vec![],award:100,funding},funds:Shares::default(),conditions:Conditions{inflow,essential:demand,other_essentials_met:true,decay_bps:2000,maintenance,request:None}}}
fn root()->Recovery{Recovery::new(Infrastructure::genesis(Engine::genesis()))}
#[test]fn recovery(){let f=[input(40,20,800,0)];let a=root().advance(&input(40,20,500,3),&f).unwrap();assert_eq!(a.decision,Decision::Scarcity);let b=a.next.advance(&input(40,20,800,3),&f).unwrap();assert_eq!(b.next.rate(),0);let c=b.next.advance(&input(40,20,800,3),&f).unwrap();assert_eq!(c.next.rate(),25);}
#[test]fn terminal_equal(){let x=root().advance(&input(0,20,800,6),&[input(0,20,800,0)]).unwrap();assert_eq!(x.decision,Decision::Accepted);assert_eq!(x.frame.maintenance,3);assert_eq!(x.frame.next.stock(),77);}
#[test]fn abundant_pass(){let x=root().advance(&input(40,20,800,6),&[input(40,20,800,0)]).unwrap();assert_eq!(x.decision,Decision::Accepted);assert_eq!(x.frame.maintenance,3);}
#[test]fn grid(){for inflow in [0,20,40]{for demand in [10,30,90]{for funds in [0,500,800]{let mut s=root();for t in 0..360{let i=input(if t%7==0{0}else{inflow},demand,funds,6);let f=[input(inflow,demand,funds,0),input(0,demand,funds,0)];let a=s.advance(&i,&f).unwrap();assert_eq!(a,s.advance(&i,&f).unwrap());assert!(a.next.rate()<=100);assert!(!a.frame.blocked||a.frame.maintenance==0);s=a.next;}}}}}
